class MedianFinder:
    def __init__(self):
        self.small = []      # max-heap (negated): lower half
        self.large = []      # min-heap: upper half

    def add(self, num):
        heapq.heappush(self.small, -num)                    # always via small
        heapq.heappush(self.large, -heapq.heappop(self.small))  # keep order
        if len(self.large) > len(self.small):               # keep balance
            heapq.heappush(self.small, -heapq.heappop(self.large))

    def median(self):
        if len(self.small) > len(self.large):
            return -self.small[0]
        return (-self.small[0] + self.large[0]) / 2

def subsets(nums):
    out, path = [], []
    def backtrack(start):
        out.append(path[:])              # copy — path keeps mutating
        for i in range(start, len(nums)):
            path.append(nums[i])         # choose
            backtrack(i + 1)             # explore (i to allow reuse)
            path.pop()                   # un-choose
    backtrack(0)
    return out

def combination_sum(nums, target):
    out, path = [], []
    def backtrack(start, remaining):
        if remaining == 0:
            out.append(path[:]); return
        if remaining < 0:
            return                       # prune
        for i in range(start, len(nums)):
            path.append(nums[i])
            backtrack(i, remaining - nums[i])   # i → reuse allowed
            path.pop()
    backtrack(0, target)
    return out

def single_number(nums):
    out = 0
    for n in nums:
        out ^= n              # pairs cancel
    return out

def missing_number(nums):
    out = len(nums)
    for i, n in enumerate(nums):
        out ^= i ^ n          # index cancels value
    return out

import heapq

def k_largest(nums, k):
    heap = []
    for n in nums:
        heapq.heappush(heap, n)
        if len(heap) > k:
            heapq.heappop(heap)      # drop the weakest winner
    return heap                       # heap[0] is the k-th largest

def top_k_frequent(nums, k):
    from collections import Counter
    counts = Counter(nums)
    return [v for v, _ in heapq.nlargest(k, counts.items(), key=lambda kv: kv[1])]

def top_k_frequent_bucket(nums, k):   # O(N), no heap
    from collections import Counter
    counts = Counter(nums)
    buckets = [[] for _ in range(len(nums) + 1)]
    for val, c in counts.items():
        buckets[c].append(val)
    out = []
    for c in range(len(buckets) - 1, 0, -1):
        for val in buckets[c]:
            out.append(val)
            if len(out) == k:
                return out

def two_sum(nums, target):
    seen = {}                       # value → index
    for i, n in enumerate(nums):
        if target - n in seen:      # ask for the complement first
            return [seen[target - n], i]
        seen[n] = i
    return []

def group_anagrams(words):
    from collections import defaultdict
    groups = defaultdict(list)
    for w in words:
        key = tuple(sorted(w))      # canonical signature
        groups[key].append(w)
    return list(groups.values())

def longest_consecutive(nums):
    s = set(nums)
    best = 0
    for n in s:
        if n - 1 in s:
            continue                # not a sequence head — skip
        length = 1
        while n + length in s:
            length += 1
        best = max(best, length)
    return best

def is_valid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False          # closed the wrong thing, or nothing
        else:
            stack.append(ch)
    return not stack                  # leftovers ⇒ unclosed

def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t in '+-*/' and len(t) == 1:
            b, a = stack.pop(), stack.pop()      # b popped first!
            stack.append({'+': a + b, '-': a - b, '*': a * b,
                          '/': int(a / b)}[t])
        else:
            stack.append(int(t))
    return stack[0]

class MinStack:                        # aggregate stored per entry
    def __init__(self):
        self.stack = []                # (value, min at this depth)
    def push(self, val):
        cur = min(val, self.stack[-1][1]) if self.stack else val
        self.stack.append((val, cur))
    def pop(self):    self.stack.pop()
    def top(self):    return self.stack[-1][0]
    def getMin(self): return self.stack[-1][1]

def next_greater(nums):
    out = [-1] * len(nums)
    stack = []                              # indices, values decreasing
    for i, n in enumerate(nums):
        while stack and nums[stack[-1]] < n:
            out[stack.pop()] = n            # answer found on POP
        stack.append(i)
    return out

def max_sliding_window(nums, k):
    from collections import deque
    dq = deque()                            # indices, values decreasing
    out = []
    for i, n in enumerate(nums):
        while dq and nums[dq[-1]] < n:
            dq.pop()                        # dominated — will never be max
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()                    # slid out of the window
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_word = True

    def _walk(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def search(self, word):
        node = self._walk(word)
        return bool(node and node.is_word)

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

from collections import deque

def count_islands(grid):
    rows, cols = len(grid), len(grid[0])

    def sink(r, c):                              # DFS: consume the region
        if not (0 <= r < rows and 0 <= c < cols) or grid[r][c] != '1':
            return
        grid[r][c] = '0'                         # mark visited
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            sink(r + dr, c + dc)

    return sum(sink(r, c) or 1
               for r in range(rows) for c in range(cols)
               if grid[r][c] == '1')

